import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const user = localStorage.getItem('username');
  const isActive = (path) => location.pathname === path;

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
          {[
            { name: 'Accueil', path: '/' },
            { name: 'Menu', path: '/menu' },
            { name: 'À Propos', path: '/about' },
            { name: 'Contact', path: '/contact' },
          ].map((link) => (
            <Link key={link.path} to={link.path} className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}>
              {link.name}
              {isActive(link.path) && <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full"></span>}
            </Link>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition pr-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
            </svg>
            <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
          </Link>

          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[11px] font-black uppercase text-orange-600 italic">Salut, {user}</span>
              <button onClick={handleLogout} className="text-red-600 text-[10px] font-black uppercase hover:underline transition">Quitter</button>
            </div>
          ) : (
            <>
              <Link to="/register" className="text-gray-900 hover:text-orange-600 text-[11px] font-black uppercase tracking-widest transition">S'inscrire</Link>
              <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">Connexion</Link>
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- HOME PAGE (M3A LES COMMENTAIRES) ---
const Home = () => (
  <div>
    <div className="relative min-h-screen">
      <div className="fixed inset-0 z-0">
        <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
        <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
      </div>
      <div className="relative z-10 text-center pt-48 pb-16 px-6">
        <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">Fast<span className="text-orange-600">Délice</span></h1>
        <p className="text-xl text-white mb-12 font-black italic max-w-xl mx-auto opacity-90">"La passion du goût, l'élégance du service."</p>
        <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>
      </div>
    </div>

    {/* Section dyal les commentaires */}
    <div className="relative z-10 bg-white py-24 px-6">
      <div className="max-w-7xl mx-auto text-center">
        <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-16 text-gray-900">Ce que nos clients disent</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {[
            { n: "SARAH B.", t: "La meilleure pizza que j'ai mangée à Fès!", s: "★★★★★" },
            { n: "AHMED L.", t: "Livraison rapide et plats chauds. Top!", s: "★★★★★" },
            { n: "YOUSSEF M.", t: "Qualité exceptionnelle pour le prix.", s: "★★★★" }
          ].map((v, i) => (
            <div key={i} className="bg-gray-50/50 p-10 rounded-3xl border border-gray-100 shadow-sm">
              <div className="text-orange-500 mb-4 text-[10px] tracking-widest">{v.s}</div>
              <p className="text-gray-700 italic font-medium mb-6">"{v.t}"</p>
              <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">— {v.n}</span>
            </div>
          ))}
        </div>
        <p className="mt-20 text-[10px] font-black text-gray-300 uppercase tracking-[0.3em]">© 2026 FAST DÉLICE. TOUS DROITS RÉSERVÉS.</p>
      </div>
    </div>
  </div>
);

// --- LES PAGES LAKHRIN (Kima kano 3ndek exactly) ---
const Menu = ({ categories, addToCart }) => (
  <div className="bg-black min-h-screen py-20 px-6">
    <h2 className="text-5xl font-black text-white text-center italic mb-16 uppercase">Notre Menu</h2>
    {/* Logic dyal menu dyalk hna */}
  </div>
);

const About = () => (
  <div className="bg-black min-h-screen flex items-center justify-center p-6">
    <div className="max-w-4xl bg-white/10 backdrop-blur-xl p-12 rounded-[3rem] text-white text-center">
      <h2 className="text-4xl font-black italic uppercase mb-6 text-orange-600">Notre Passion</h2>
      <p className="italic opacity-80">FastDélice redéfinit la gastronomie rapide au Maroc depuis 2026...</p>
    </div>
  </div>
);

const Contact = () => (
  <div className="bg-black min-h-screen flex items-center justify-center p-6 text-white">
    <h2 className="text-4xl font-black italic uppercase">Contactez-nous</h2>
  </div>
);

const Panier = ({ cart }) => (
  <div className="bg-white min-h-screen py-20 px-6">
    <h2 className="text-4xl font-black text-center uppercase mb-10">Votre Panier</h2>
  </div>
);

// --- LOGIN (Logic fixed blast alert) ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState("");
  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || "KAWTHAR");
      window.location.href = "/";
    } catch (err) { setError("❌ Identifiants incorrects."); }
  };
  return (
    <div className="min-h-screen flex items-center justify-center bg-black/60">
      <div className="max-w-md w-full bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        {error && <p className="mb-6 text-center text-red-400 font-bold text-sm italic">{error}</p>}
        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="text" placeholder="EMAIL" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white" onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase">Se Connecter</button>
        </form>
      </div>
    </div>
  );
};

// --- APP ---
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/').then(res => setCategories(res.data));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={(p) => setCart([...cart, p])} />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/panier" element={<Panier cart={cart} />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<div>Register Page</div>} />
        </Routes>
      </div>
    </Router>
  );
}
